module recycling_optimization (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] ax, ay,\n    input wire [31:0] bx, by,\n    input wire [31:0] tx, ty,\n    input wire [2:0] num_bottles,\n    input wire [31:0] bottle_x [0:7],\n    input wire [31:0] bottle_y [0:7],\n    output reg [63:0] total_distance,\n    output reg done\n);\n\n    // States\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] CALC_DISTS      = 3'd1;\n    localparam [2:0] FIND_ADIL_SAVE  = 3'd2;\n    localparam [2:0] FIND_BERA_SAVE  = 3'd3;\n    localparam [2:0] CALC_RESULT     = 3'd4;\n    \n    reg [2:0] state;\n    reg [2:0] counter;\n    reg [3:0] cycle_count;\n    \n    // Distance arrays\n    reg [63:0] dist_bin [0:7];\n    reg [63:0] dist_adil [0:7];\n    reg [63:0] dist_bera [0:7];\n    \n    // Savings tracking\n    reg [63:0] best_savings [0:1];\n    reg [2:0] best_idx [0:1];\n    \n    // Fixed-point multiplication\n    function automatic [63:0] fp_mult;\n        input [31:0] a, b;\n        reg [63:0] prod;\n        begin\n            prod = {{32{a[31]}}, a} * {{32{b[31]}}, b};\n            fp_mult = prod >>> 16;\n        end\n    endfunction\n    \n    // Distance function\n    function automatic [63:0] calc_distance;\n        input [31:0] x1, y1, x2, y2;\n        reg [31:0] dx, dy;\n        reg [63:0] dx_sq, dy_sq, sum_sq;\n        begin\n            dx = (x1 > x2) ? (x1 - x2) : (x2 - x1);\n            dy = (y1 > y2) ? (y1 - y2) : (y2 - y1);\n            dx_sq = fp_mult(dx, dx);\n            dy_sq = fp_mult(dy, dy);\n            sum_sq = dx_sq + dy_sq;\n            calc_distance = sum_sq[63] ? 64'd0 : ({32'd0, sum_sq[31:0]} + (sum_sq << 16)) / 128;  // Approximation\n        end\n    endfunction\n    \n    // Savings calculation (combinational)\n    wire [63:0] savings_adil [0:7];\n    wire [63:0] savings_bera [0:7];\n    generate\n        genvar i;\n        for (i = 0; i < 8; i = i + 1) begin: savings\n            assign savings_adil[i] = (i < num_bottles) ? (dist_bin[i] - dist_adil[i]) : 64'd0;\n            assign savings_bera[i] = (i < num_bottles) ? (dist_bin[i] - dist_bera[i]) : 64'd0;\n        end\n    endgenerate\n    \n    // Sequential logic\n    integer j;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            total_distance <= 64'd0;\n            cycle_count <= 4'd0;\n            \n            for (j = 0; j < 8; j = j + 1) begin\n                dist_bin[j] <= 64'd0;\n                dist_adil[j] <= 64'd0;\n                dist_bera[j] <= 64'd0;\n            end\n            \n            best_savings[0] <= 64'd0;\n            best_savings[1] <= 64'd0;\n            best_idx[0] <= 3'd0;\n            best_idx[1] <= 3'd0;\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= CALC_DISTS;\n                        counter <= 3'd0;\n                        cycle_count <= cycle_count + 4'd1;\n                    end\n                end\n                \n                CALC_DISTS: begin\n                    if (counter < num_bottles) begin\n                        dist_bin[counter] <= calc_distance(tx, ty, bottle_x[counter], bottle_y[counter]);\n                        dist_adil[counter] <= calc_distance(ax, ay, bottle_x[counter], bottle_y[counter]);\n                        dist_bera[counter] <= calc_distance(bx, by, bottle_x[counter], bottle_y[counter]);\n                        counter <= counter + 3'd1;\n                    end\n                    else begin\n                        state <= FIND_ADIL_SAVE;\n                        counter <= 3'd0;\n                        best_savings[0] <= 64'h8000000000000000;  // Min value\n                        best_savings[1] <= 64'h8000000000000000;\n                    end\n                    cycle_count <= cycle_count + 4'd1;\n                end\n                \n                FIND_ADIL_SAVE: begin\n                    if (counter < num_bottles) begin\n                        if (savings_adil[counter] > best_savings[0]) begin\n                            best_savings[1] <= best_savings[0];\n                            best_idx[1] <= best_idx[0];\n                            best_savings[0] <= savings_adil[counter];\n                            best_idx[0] <= counter;\n                        end\n                        else if (savings_adil[counter] > best_savings[1]) begin\n                            best_savings[1] <= savings_adil[counter];\n                            best_idx[1] <= counter;\n                        end\n                        counter <= counter + 3'd1;\n                    end\n                    else begin\n                        state <= FIND_BERA_SAVE;\n                        counter <= 3'd0;\n                    end\n                    cycle_count <= cycle_count + 4'd1;\n                end\n                \n                FIND_BERA_SAVE: begin\n                    if (counter < num_bottles && counter != best_idx[0]) begin  // Skip best Adil bottle\n                        if (savings_bera[counter] > best_savings[1]) begin\n                            best_savings[1] <= savings_bera[counter];\n                            best_idx[1] <= counter;\n                        end\n                        counter <= counter + 3'd1;\n                    end\n                    else if (counter < num_bottles) begin\n                        counter <= counter + 3'd1;\n                    end\n                    else begin\n                        state <= CALC_RESULT;\n                    end\n                    cycle_count <= cycle_count + 4'd1;\n                end\n                \n                CALC_RESULT: begin\n                    // Base total = 2*(sum of all dist_bin)\n                    // Subtract best savings\n                    total_distance <= (dist_bin[0] + dist_bin[1] + dist_bin[2] + dist_bin[3] + \n                                      dist_bin[4] + dist_bin[5] + dist_bin[6] + dist_bin[7]) * 64'd65536 * 2\n                                      - (best_savings[0] + best_savings[1]);\n                    done <= 1'b1;\n                    state <= IDLE;\n                    cycle_count <= 4'd0;\n                end\n                \n                default: state <= IDLE;\n            endcase\n            \n            // Timeout safety\n            if (cycle_count > 4'd12) begin\n                state <= IDLE;\n                done <= 1'b1;  // Error handling\n            end\n        end\n    end\n\nendmodule